import{_ as a,c as e,o as t,a4 as r}from"./chunks/framework.D5y910bP.js";const u=JSON.parse('{"title":"CUDA RL Path-tracer","description":"","frontmatter":{"date":"2018-05-07T00:00:00.000Z","tags":["cuda","pathtracer","research","rl","ml","ai"],"title":"CUDA RL Path-tracer"},"headers":[],"relativePath":"blog/rl-pathtracer.md","filePath":"blog/rl-pathtracer.md","lastUpdated":1739289997000}'),s={name:"blog/rl-pathtracer.md"},i=r('<h1 id="cuda-rl-path-tracing" tabindex="-1">CUDA RL Path Tracing <a class="header-anchor" href="#cuda-rl-path-tracing" aria-label="Permalink to &quot;CUDA RL Path Tracing&quot;">​</a></h1><p>Reinforcement Learning based Path Tracer in CUDA (Research Project)</p><p>Github <a href="https://github.com/repalash/CUDAPathTracerRL" target="_blank" rel="noreferrer">https://github.com/repalash/CUDAPathTracerRL</a></p><p>Monte Carlo based path tracer with both CPU(with openMP) and GPU support(with CUDA).</p><p>CUDA based renderer optionally uses Reinforcement Learning (<strong>based on ideas from NVIDIA paper</strong>: <a href="https://arxiv.org/abs/1701.07403" target="_blank" rel="noreferrer">Learning Light Transport the reinforced way</a>).</p><p>RL assumes that every ray has 8 actions available to choose from in each bounce(based on the 8 octants). So a QTable is built upon that and the most optimum path is chosen. With time, the rays learn the best path to take to reach the light source. Since this is online Reinforcement Learning, there is no training period and the values converge pretty fast.</p><h2 id="renders" tabindex="-1">Renders <a class="header-anchor" href="#renders" aria-label="Permalink to &quot;Renders&quot;">​</a></h2><p><img src="https://raw.githubusercontent.com/repalash/CUDAPathTracerRL/master/images/image_2.PNG" alt="Render 1"><img src="https://raw.githubusercontent.com/repalash/CUDAPathTracerRL/master/images/image_1.PNG" alt="Render 1"><img src="https://raw.githubusercontent.com/repalash/CUDAPathTracerRL/master/images/image_4.PNG" alt="Render 1"><img src="https://raw.githubusercontent.com/repalash/CUDAPathTracerRL/master/images/image_3.PNG" alt="Render 1"></p><h2 id="cpu-vs-gpu-comparision-no-rl" tabindex="-1">CPU vs GPU comparision(no RL) <a class="header-anchor" href="#cpu-vs-gpu-comparision-no-rl" aria-label="Permalink to &quot;CPU vs GPU comparision(no RL)&quot;">​</a></h2><p><img src="https://raw.githubusercontent.com/repalash/CUDAPathTracerRL/master/images/slide_2.jpg" alt="CPU vs GPU"></p><h2 id="path-tracing-with-reinforcement-learning-on-gpu" tabindex="-1">Path tracing with Reinforcement learning on GPU <a class="header-anchor" href="#path-tracing-with-reinforcement-learning-on-gpu" aria-label="Permalink to &quot;Path tracing with Reinforcement learning on GPU&quot;">​</a></h2><p><img src="https://raw.githubusercontent.com/repalash/CUDAPathTracerRL/master/images/slide_3.jpg" alt="RL vs GPU"><img src="https://raw.githubusercontent.com/repalash/CUDAPathTracerRL/master/images/slide_4.jpg" alt="RL vs GPU working"></p><p>We can see here that in the same time, the rays were able to find a better path for indirect lighting, hence better illumination.</p><h3 id="more-comparisions" tabindex="-1">More comparisions <a class="header-anchor" href="#more-comparisions" aria-label="Permalink to &quot;More comparisions&quot;">​</a></h3><p><img src="https://raw.githubusercontent.com/repalash/CUDAPathTracerRL/master/images/slide_5.jpg" alt="RL vs GPU"><img src="https://raw.githubusercontent.com/repalash/CUDAPathTracerRL/master/images/slide_6.jpg" alt="RL vs GPU"><img src="https://raw.githubusercontent.com/repalash/CUDAPathTracerRL/master/images/slide_7.jpg" alt="RL vs GPU"></p><h2 id="issues-with-rl-based-lighting" tabindex="-1">Issues with RL based lighting <a class="header-anchor" href="#issues-with-rl-based-lighting" aria-label="Permalink to &quot;Issues with RL based lighting&quot;">​</a></h2><p><img src="https://raw.githubusercontent.com/repalash/CUDAPathTracerRL/master/images/slide_1.jpg" alt="RL issues"></p>',17),n=[i];function h(o,c,l,p,m,g){return t(),e("div",null,n)}const P=a(s,[["render",h]]);export{u as __pageData,P as default};
